"""AWS Marketplace license verification for container contract pricing.

Rasa Pro is listed as a Container Based Offering with contract pricing, which
requires an AWS License Manager integration. Customers buy a quantity of
conversations or of users; that quantity is negotiated per private offer.

There is deliberately **no metering and no enforcement** here — the commercial
model is an honesty policy. This module proves that a valid Marketplace license
exists and records the entitlement quantities so they are already present in
the process if enforcement is ever added. It never stops a customer's server:
every failure is a warning, because the check protects nothing that a customer
could not bypass by leaving the feature switched off.
"""

import asyncio
import os
import uuid
from asyncio import AbstractEventLoop
from typing import Any, Dict, Optional, Text

import boto3
import structlog
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError
from sanic import Sanic

MARKETPLACE_ENABLED_ENV_VAR = "RASA_AWS_MARKETPLACE_ENABLED"
MARKETPLACE_PRODUCT_ID_ENV_VAR = "RASA_AWS_MARKETPLACE_PRODUCT_ID"
MARKETPLACE_REGION_ENV_VAR = "RASA_AWS_MARKETPLACE_REGION"

AWS_MARKETPLACE_KEY_FINGERPRINT = "aws:294406891311:AWS/Marketplace:issuer-fingerprint"
CHECKOUT_TYPE = "PROVISIONAL"

# The default entitlement present on every Marketplace-issued license. Checking
# it out consumes none of the units the customer bought, and it keeps this
# module free of the pricing dimension names — adding or renaming a Marketplace
# dimension is therefore not a code change here.
ENTITLEMENT_NAME = "AWS::Marketplace::Usage"

# AWS's Containers Anywhere guidance issues Marketplace licenses in us-east-1;
# without a fallback an unset AWS_REGION surfaces as a confusing NoRegionError.
DEFAULT_REGION = "us-east-1"

CONNECT_TIMEOUT_SECONDS = 5
READ_TIMEOUT_SECONDS = 10
MAX_ATTEMPTS = 2

# AWS recommends re-checking every 15 minutes in AWS and daily for Containers
# Anywhere; hourly keeps the logged entitlements current between those bounds.
RECHECK_INTERVAL_SECONDS = 60 * 60

structlogger = structlog.get_logger()


def is_marketplace_licensing_enabled() -> bool:
    """Return whether AWS Marketplace licensing is enabled via environment."""
    return os.environ.get(MARKETPLACE_ENABLED_ENV_VAR, "").strip().lower() == "true"


def validate_marketplace_license() -> Dict[Text, Any]:
    """Verify an active AWS Marketplace subscription and read its entitlements.

    No-op when :func:`is_marketplace_licensing_enabled` is false. Otherwise
    performs a PROVISIONAL CheckoutLicense call — which is itself the
    entitlement check, since an unentitled buyer gets an exception rather than
    an empty response — and then reads the full entitlement set for telemetry.

    There is no matching CheckInLicense or ExtendLicenseConsumption call: the
    provisional checkout returns to the pool on its own after 60 minutes, and
    because ``AWS::Marketplace::Usage`` is checked out with ``Unit: "None"``
    nothing is drawn from the customer's purchased pool in the first place.

    A failure never stops the server: it is logged as a warning and an empty
    mapping is returned. Uses the default boto3 credential chain.

    Returns:
        Entitlement names mapped to their quantity, empty when licensing is
        disabled, when validation failed, or when the entitlement details could
        not be read.
    """
    if not is_marketplace_licensing_enabled():
        return {}

    product_id = os.environ.get(MARKETPLACE_PRODUCT_ID_ENV_VAR, "").strip()
    if not product_id:
        _log_checkout_failure(
            "MissingProductId",
            "",
            f"AWS Marketplace licensing is enabled but "
            f"`{MARKETPLACE_PRODUCT_ID_ENV_VAR}` is not set. "
            "Set it to the Product ID from the AWS Marketplace Management Portal.",
        )
        return {}

    try:
        license_client = _create_license_manager_client()
        response = license_client.checkout_license(
            **_build_checkout_request(product_id)
        )
    except ClientError as error:
        _log_checkout_failure(
            _error_code(error),
            product_id,
            "Failed to validate AWS Marketplace license. "
            "Ensure the deployment has a valid Marketplace subscription "
            f"and that `{MARKETPLACE_PRODUCT_ID_ENV_VAR}` is set to the "
            "Product ID from the AWS Marketplace Management Portal.",
        )
        return {}
    except BotoCoreError as error:
        _log_checkout_failure(
            _error_code(error),
            product_id,
            "Failed to validate AWS Marketplace license due to an AWS client error. "
            "Verify IAM credentials and network connectivity.",
        )
        return {}

    details = _fetch_license_details(license_client, response.get("LicenseArn"))
    entitlements = {
        entitlement["Name"]: _entitlement_amount(entitlement)
        for entitlement in details.get("Entitlements") or []
        if entitlement.get("Name")
    }
    _log_checkout_verified(product_id, entitlements, details)

    return entitlements


async def start_marketplace_license_recheck(
    app: Sanic, loop: AbstractEventLoop
) -> None:
    """Start the periodic re-check as a Sanic ``after_server_start`` listener."""
    if not is_marketplace_licensing_enabled():
        return

    app.add_task(
        _recheck_marketplace_license_periodically(),
        name="marketplace_license_recheck",
    )


async def _recheck_marketplace_license_periodically() -> None:
    """Re-validate hourly so renewals, upgrades and cancellations show up."""
    while True:
        await asyncio.sleep(RECHECK_INTERVAL_SECONDS)
        try:
            await asyncio.to_thread(validate_marketplace_license)
        except asyncio.CancelledError:
            raise
        except Exception as error:
            # The re-check is informational; any unexpected error must leave
            # both this loop and the server running.
            structlogger.warning(
                "license.marketplace.recheck.failed",
                error_code=_error_code(error),
            )


def _create_license_manager_client() -> Any:
    """Create a License Manager client with short, explicit timeouts.

    Without a `Config` the botocore defaults allow a minute per attempt plus
    retries, which would stall startup. The region falls back to
    :data:`DEFAULT_REGION` only when neither the Rasa override nor the standard
    boto3 resolution (environment, shared config, instance metadata) supplies
    one.
    """
    session = boto3.session.Session()
    region = (
        os.environ.get(MARKETPLACE_REGION_ENV_VAR, "").strip()
        or session.region_name
        or DEFAULT_REGION
    )

    return session.client(
        "license-manager",
        region_name=region,
        config=Config(
            connect_timeout=CONNECT_TIMEOUT_SECONDS,
            read_timeout=READ_TIMEOUT_SECONDS,
            retries={"max_attempts": MAX_ATTEMPTS, "mode": "standard"},
        ),
    )


def _build_checkout_request(product_id: Text) -> Dict[Text, Any]:
    """Build the CheckoutLicense request payload for `product_id`.

    Args:
        product_id: Product ID from the AWS Marketplace Management Portal.

    Returns:
        Request kwargs for license-manager CheckoutLicense.
    """
    return {
        "ProductSKU": product_id,
        "CheckoutType": CHECKOUT_TYPE,
        "KeyFingerprint": AWS_MARKETPLACE_KEY_FINGERPRINT,
        "Entitlements": [{"Name": ENTITLEMENT_NAME, "Unit": "None"}],
        "ClientToken": str(uuid.uuid4()),
    }


def _fetch_license_details(client: Any, license_arn: Optional[Text]) -> Dict[Text, Any]:
    """Return the GetLicense ``License`` body, or an empty mapping.

    `CheckoutLicense` only echoes back the entitlements that were requested and
    returns the `EntitlementData` shape, which carries no quantities. GetLicense
    returns the fuller `Entitlement` shape for every entitlement on the license.

    This is informational only — the checkout has already proved the license is
    valid — so every failure is logged and swallowed.

    Args:
        client: License Manager client.
        license_arn: `LicenseArn` from the CheckoutLicense response.

    Returns:
        The `License` body, or an empty mapping when it could not be read.
    """
    if not license_arn:
        return {}

    try:
        return client.get_license(LicenseArn=license_arn).get("License") or {}
    except (ClientError, BotoCoreError) as error:
        structlogger.warning(
            "license.marketplace.details.unavailable",
            error_code=_error_code(error),
            event_info=(
                "Could not read AWS Marketplace entitlement details. The license "
                "itself was verified; only the reported entitlement quantities "
                "are missing. Verify the deployment grants "
                "`license-manager:GetLicense`."
            ),
        )
        return {}


def _entitlement_amount(entitlement: Dict[Text, Any]) -> Any:
    """Return the quantity of `entitlement`.

    AWS documents `MaxCount` and `Value` as alternatives: `MaxCount` is
    populated when the unit is not ``None``, `Value` when it is.
    """
    if entitlement.get("Unit") == "None":
        return entitlement.get("Value")
    return entitlement.get("MaxCount")


def _error_code(error: Exception) -> Text:
    """Return the AWS error code for `error`, falling back to its type name."""
    if isinstance(error, ClientError):
        return error.response.get("Error", {}).get("Code", "ClientError")
    return type(error).__name__


def _log_checkout_failure(error_code: Text, product_id: Text, event_info: Text) -> None:
    """Warn that license validation failed, without interrupting the server.

    Args:
        error_code: AWS error code, or a short code for a local failure.
        product_id: Configured Marketplace product ID, empty when unset.
        event_info: Operator-facing guidance for resolving the failure. The
            process keeps running, so this log line is the only place the
            operator will see it.
    """
    structlogger.warning(
        "license.marketplace.checkout.failed",
        error_code=error_code,
        product_id=product_id,
        entitlement=ENTITLEMENT_NAME,
        event_info=event_info,
    )


def _log_checkout_verified(
    product_id: Text,
    entitlements: Dict[Text, Any],
    details: Dict[Text, Any],
) -> None:
    structlogger.info(
        "license.marketplace.checkout.verified",
        product_id=product_id,
        entitlement=ENTITLEMENT_NAME,
        entitlements=entitlements,
        license_status=details.get("Status"),
        expires_at=(details.get("Validity") or {}).get("End"),
    )
